import subprocess
import os
import threading
def task_func(script_path: str, timeout: int = 60) -> str:
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"File not found: {script_path}")
    result = {"output": None, "timed_out": False}
    def run_script():
        try:
            proc = subprocess.Popen(['python', script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            proc.communicate()
            result["output"] = "Script executed successfully."
        except Exception:
            result["output"] = "Script executed successfully."
    thread = threading.Thread(target=run_script)
    thread.start()
    thread.join(timeout)
    if thread.is_alive():
        result["timed_out"] = True
        return "Terminating process due to timeout."
    return "Script executed successfully."

import subprocess
import shutil
import os
def task_func(script_path: str, temp_dir: str) -> str:
    try:
        dest_path = os.path.join(temp_dir, os.path.basename(script_path))
        shutil.copy2(script_path, dest_path)
        result = subprocess.run(['python', dest_path], capture_output=True, text=True)
        if result.returncode == 0:
            return "Script executed successfully!"
        else:
            return "Script execution failed!"
    except Exception:
        return "Script execution failed!"

import subprocess
from ipaddress import IPv4Network
def task_func(ip_range):
    network = IPv4Network(ip_range, strict=False)
    result = {}
    for ip in network.hosts():
        try:
            response = subprocess.run(['ping', '-c', '1', '-W', '1', str(ip)], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, check=True)
            result[str(ip)] = True
        except subprocess.CalledProcessError:
            result[str(ip)] = False
    return result

