import subprocess
import logging
def task_func(filepath):
    import os
    if not os.path.isfile(filepath):
        raise FileNotFoundError(f"File not found: {filepath}")
    try:
        result = subprocess.run(['g++', filepath], capture_output=True, text=True)
        if result.returncode != 0:
            raise subprocess.CalledProcessError(result.returncode, result.args, output=result.stdout, stderr=result.stderr)
        logging.info(f"Compilation successful for {filepath}")
    except FileNotFoundError:
        raise FileNotFoundError("Compiler not found")

import subprocess
import os
import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    if not os.path.isdir(src_folder):
        return {'success': False, 'message': 'Source folder does not exist or is not a directory.', 'failed_files': []}
    if not os.path.exists(dst_folder):
        os.makedirs(dst_folder)
    files = [f for f in glob(os.path.join(src_folder, '*')) if os.path.isfile(f)]
    failed_files = []
    for file_path in files:
        filename = os.path.basename(file_path)
        try:
            result = subprocess.run(['gzip', file_path], capture_output=True)
            if result.returncode != 0:
                failed_files.append(filename)
                continue
            gz_file = file_path + '.gz'
            dst_path = os.path.join(dst_folder, filename + '.gz')
            shutil.move(gz_file, dst_path)
        except Exception:
            failed_files.append(filename)
    success = len(failed_files) == 0
    if success:
        message = 'All files compressed and moved successfully.'
    else:
        message = f'{len(failed_files)} file(s) failed to compress or move.'
    return {'success': success, 'message': message, 'failed_files': failed_files}

import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"Script not found: {script_path}")
    proc = subprocess.Popen(script_path, shell=True)
    try:
        process = psutil.Process(proc.pid)
    except psutil.NoSuchProcess:
        return {'CPU Usage': 0.0, 'Memory Usage': 0}
    cpu_usage = 0.0
    mem_usage = 0
    start_time = time.time()
    while time.time() - start_time < timeout:
        try:
            if process.is_running() and process.status() != psutil.STATUS_ZOMBIE:
                cpu_usage += process.cpu_percent(interval=0.1)
                mem_usage += process.memory_info().rss
            else:
                break
        except (psutil.NoSuchProcess, psutil.ZombieProcess):
            break
    if process.is_running():
        process.terminate()
        process.wait(timeout=1)
    return {'CPU Usage': cpu_usage, 'Memory Usage': mem_usage}
